window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-d7a7d5f68b7c7acc"]={"versions": [{"id": "FIG-d7a7d5f68b7c7acc", "releases": ["R4.2.2", "R4.3.1", "R18-10_R4.4.0_R1.5.0", "R19-11", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Komponentendiagramm im Kontext des AUTOSAR-V-Modells (Software Component Template, TPS_SoftwareComponentTemplate). Dargestellt ist eine unzulässige kompositionelle Delegationsarchitektur (<code>SwConnector</code> bzw. <code>DelegationSwConnector</code>) zwischen Software-Komponenten über Kompositionsgrenzen hinweg. Das Diagramm verdeutlicht eine fehlerhafte Port-Schnittstellen-Abbildung bei der Delegation von Datenelementen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Composition Software Components (äußere Rahmen):</strong> Zwei übergeordnete Kompositions-Komponenten (links Sender-Komposition, rechts Empfänger-Komposition).</li>\n<li><strong>Atomic Software Components (innere graue Rechtecke):</strong> Je zwei enthaltene Komponentenprototypen pro Komposition (zwei sendende Komponenten links, zwei empfangende Komponenten rechts).</li>\n<li><strong>Ports & Port-Interfaces (Quadrate mit Dreieckssymbolen):</strong></li>\n<li>Sender-Ports (Dreieck zeigt nach außen): Linke interne Komponenten stellen Datenelemente <code>{A,B}</code> bzw. <code>{B,C}</code> bereit.</li>\n<li>Delegations-P-Port (äußerer Port der linken Komposition): Ausgelegt auf <code>{A,C,E}</code>.</li>\n<li>Delegations-R-Port (äußerer Port der rechten Komposition): Ausgelegt auf <code>{A,C,E}</code>.</li>\n<li>Receiver-Ports (Dreieck zeigt nach innen): Rechte interne Komponenten erwarten Datenelemente <code>{A}</code> bzw. <code>{C,E}</code>.</li>\n<li><strong>Connectors:</strong></li>\n<li><code>DelegationSwConnector</code>: Verbindet interne P-Ports mit dem äußeren P-Port (Senderseite) bzw. den äußeren R-Port mit den internen R-Ports (Empfängerseite).</li>\n<li><code>AssemblySwConnector</code>: Verbindet die beiden äußeren Kompositions-Ports auf Systemebene.</li>\n<li><strong>Fehler-Indikator:</strong> Ein unzufriedenes Smiley-Symbol markiert die linke Delegationskonfiguration als ungültig/fehlerhaft.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Schnittstellen- und Delegationsabbildung. Die Übertragung erfolgt gerichtet von den beiden Quellkomponenten über die delegierenden Konnektoren zur Zielkomposition und weiter zu den Zielkomponenten. Ein dynamischer Ablauf findet nicht statt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm dient als normatives Negativbeispiel für die Validierung von <code>DelegationSwConnector</code>-Strukturen:</p>\n<ul class=\"fig-list\">\n<li><strong>Fehlerhafte Vereinigung (Aggregation) auf Senderseite:</strong> Eine Zusammenführung zweier P-Ports (<code>{A,B}</code> und <code>{B,C}</code>) über Delegation auf einen gemeinsamen äußeren Port <code>{A,C,E}</code> ist unzulässig (markiert durch das Smiley-Symbol). Das Datenelement <code>B</code> wird außen nicht angeboten, während die Elemente <code>C</code> und <code>E</code> nicht konsistent von einem einzelnen internen Port bereitgestellt werden.</li>\n<li><strong>End-to-End-Inkonsistenz:</strong> Obwohl der Delegations-R-Port der rechten Komposition (<code>{A,C,E}</code>) formal die von den inneren Empfängern benötigten Teilmengen <code>{A}</code> und <code>{C,E}</code> abdecken könnte, ist die gesamte Verbindungskette ungültig, da die delegierende Aggregation senderseitig keine valide Schnittstellenkompatibilität herstellt.</li>\n<li><strong>Entwickler-Hinweis:</strong> Delegationskonnektoren dürfen nicht zur beliebigen Bündelung disjunkter oder unvollständiger Schnittstellenelemente verwendet werden; jede Delegation muss strenge Port-Interface-Kompatibilitätsregeln bezüglich Datenelementtypen und -namen erfüllen.</li>\n</ul>"}, {"id": "FIG-d82841aa652d2593", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Komponentendiagramm im Kontext des AUTOSAR-V-Modells (Software Component Template, TPS_SoftwareComponentTemplate). Dargestellt ist eine unzulässige kompositionelle Delegationsarchitektur (<code>SwConnector</code> bzw. <code>DelegationSwConnector</code>) zwischen Software-Komponenten über Kompositionsgrenzen hinweg. Das Diagramm verdeutlicht eine fehlerhafte Port-Schnittstellen-Abbildung bei der Delegation von Datenelementen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Composition Software Components (äußere Rahmen):</strong> Zwei übergeordnete Kompositions-Komponenten (links Sender-Komposition, rechts Empfänger-Komposition).</li>\n<li><strong>Atomic Software Components (innere graue Rechtecke):</strong> Je zwei enthaltene Komponentenprototypen pro Komposition (zwei sendende Komponenten links, zwei empfangende Komponenten rechts).</li>\n<li><strong>Ports & Port-Interfaces (Quadrate mit Dreieckssymbolen):</strong></li>\n<li>Sender-Ports (Dreieck zeigt nach außen): Linke interne Komponenten stellen Datenelemente <code>{A,B}</code> bzw. <code>{B,C}</code> bereit.</li>\n<li>Delegations-P-Port (äußerer Port der linken Komposition): Ausgelegt auf <code>{A,C,E}</code>.</li>\n<li>Delegations-R-Port (äußerer Port der rechten Komposition): Ausgelegt auf <code>{A,C,E}</code>.</li>\n<li>Receiver-Ports (Dreieck zeigt nach innen): Rechte interne Komponenten erwarten Datenelemente <code>{A}</code> bzw. <code>{C,E}</code>.</li>\n<li><strong>Connectors:</strong></li>\n<li><code>DelegationSwConnector</code>: Verbindet interne P-Ports mit dem äußeren P-Port (Senderseite) bzw. den äußeren R-Port mit den internen R-Ports (Empfängerseite).</li>\n<li><code>AssemblySwConnector</code>: Verbindet die beiden äußeren Kompositions-Ports auf Systemebene.</li>\n<li><strong>Fehler-Indikator:</strong> Ein unzufriedenes Smiley-Symbol markiert die linke Delegationskonfiguration als ungültig/fehlerhaft.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Schnittstellen- und Delegationsabbildung. Die Übertragung erfolgt gerichtet von den beiden Quellkomponenten über die delegierenden Konnektoren zur Zielkomposition und weiter zu den Zielkomponenten. Ein dynamischer Ablauf findet nicht statt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm dient als normatives Negativbeispiel für die Validierung von <code>DelegationSwConnector</code>-Strukturen:</p>\n<ul class=\"fig-list\">\n<li><strong>Fehlerhafte Vereinigung (Aggregation) auf Senderseite:</strong> Eine Zusammenführung zweier P-Ports (<code>{A,B}</code> und <code>{B,C}</code>) über Delegation auf einen gemeinsamen äußeren Port <code>{A,C,E}</code> ist unzulässig (markiert durch das Smiley-Symbol). Das Datenelement <code>B</code> wird außen nicht angeboten, während die Elemente <code>C</code> und <code>E</code> nicht konsistent von einem einzelnen internen Port bereitgestellt werden.</li>\n<li><strong>End-to-End-Inkonsistenz:</strong> Obwohl der Delegations-R-Port der rechten Komposition (<code>{A,C,E}</code>) formal die von den inneren Empfängern benötigten Teilmengen <code>{A}</code> und <code>{C,E}</code> abdecken könnte, ist die gesamte Verbindungskette ungültig, da die delegierende Aggregation senderseitig keine valide Schnittstellenkompatibilität herstellt.</li>\n<li><strong>Entwickler-Hinweis:</strong> Delegationskonnektoren dürfen nicht zur beliebigen Bündelung disjunkter oder unvollständiger Schnittstellenelemente verwendet werden; jede Delegation muss strenge Port-Interface-Kompatibilitätsregeln bezüglich Datenelementtypen und -namen erfüllen.</li>\n</ul>"}], "trans": [{"from": "FIG-d7a7d5f68b7c7acc", "to": "FIG-d82841aa652d2593", "fr": "R20-11", "tr": "R22-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Gesamtdiagramm: Aspektverhältnis und Linienstärken neu gerendert (flachere Boxen der inneren Software-Komponenten, verändertes Seitenverhältnis des Gesamtlayouts).</li>\n<li>Beschriftungen (<code>{A,B}</code>, <code>{B,C}</code>, <code>{A,C,E}</code>, <code>{A}</code>, <code>{C,E}</code>): Schriftart und Zeichensatz neu gesetzt.</li>\n</ul>"}]};
